INSERT INTO `investment_options` VALUES (1,'Fixed Deposit','fixed-deposit',NULL,'Low-risk bank deposits with fixed interest.','Why consider FD?','Guaranteed returns\nLow risk\nGood for emergency funds','Things to note','Interest taxed\nPenalty for early withdrawal','Low risk','low','Bank rates','https://rbi.org.in',0,1),(2,'Public Provident Fund (PPF)','ppf',NULL,'Long-term tax-efficient savings.','Why PPF?','Tax benefits\nLong-term savings\nGovernment backed','Things to note','15-year lock-in\nPartial withdrawals have rules','Low to Medium','low','Learn PPF','https://incometax.gov.in',1,1),(3,'Mutual Funds (SIP)','mutual-funds',NULL,'Start SIPs for disciplined investing.','Why SIPs?','Rupee cost averaging\nDiversified exposure\nProfessional management','Things to note','Market risk\nChoose fund based on horizon','Medium risk','medium','Explore funds','https://www.amfiindia.in',2,1),(4,'Direct Equity (Stocks)','stocks',NULL,'High-growth but higher volatility.','Why stocks?','High upside potential\nOwnership in companies','Things to note','High volatility\nRequires research','High risk','high','Market info','https://www.nseindia.com',3,1),(5,'Gold Investment','gold','lni lni-diamond','A traditional hedge against inflation','Why consider gold?','Preserves value during inflation\nActs as a safe haven asset\nHighly liquid investment','Risks & points to note','No regular income\nPrices can fluctuate short-term\nStorage costs for physical gold','Medium risk','medium','View gold prices','https://www.mcxindia.com/market-data',1,1),(6,'Systematic Investment Plan (SIP)','sip','lni lni-reload','Invest small amounts regularly','How SIP helps','Disciplined investing\nRupee cost averaging\nFlexible amounts','Things to remember','Market fluctuations\nNeeds consistency\nLong-term commitment','Medium risk','medium','SIP calculator','https://groww.in/calculators/sip-calculator',4,1),(7,'Real Estate','real-estate','lni lni-home','Property-based long-term investment','Why real estate?','Rental income\nAsset appreciation\nPhysical ownership','Challenges','High capital needed\nLow liquidity\nLegal issues','Medium–High risk','high','Property listings','https://www.99acres.com/',6,1),(8,'National Pension Scheme (NPS)','nps','lni lni-investment','Retirement-focused investment plan','Why NPS?','Tax benefits\nMarket-linked growth\nRetirement corpus','Considerations','Partial lock-in\nMarket exposure\nWithdrawal rules','Medium risk','medium','NPS portal','https://www.npscra.nsdl.co.in/',8,1),(9,'Cryptocurrency','cryptocurrency','lni lni-bitcoin','Digital assets with high volatility','Why people invest','Decentralized\nHigh return potential\nGlobal access','Major risks','Extreme volatility\nRegulatory uncertainty\nSecurity risks','Very high risk','high','Learn about crypto','https://coinmarketcap.com/',9,1),(10,'Exchange Traded Funds (ETF)','etf','lni lni-layers','Index-based low-cost investment','ETF advantages','Low expense ratio\nDiversification\nEasy trading','Limitations','Market risk\nTracking error\nRequires demat account','Medium risk','medium','ETF list','https://www.nseindia.com/market-data/exchange-traded-funds-etf',10,1);
