INSERT INTO `page_contents` VALUES (1,'home','hero_title','Manage your money. Build your future.','2026-01-07 06:13:44',3),(2,'home','hero_subtitle','Disha Finance — expense tracking, investment planning, and reminders in one place.','2026-01-07 06:13:44',3),(3,'home','feature_1','Expense tracker with smart categories and monthly insights.','2026-01-07 06:13:44',3),(4,'home','feature_2','Automated reminders for bills & investments.','2026-01-07 06:13:44',3),(5,'about','intro','Disha Finance is a student-built demo that simulates personal finance management for learning and presentation.','2026-01-07 06:13:44',3),(6,'about','mission','We make it simple to track expenses, plan investments, and reach financial goals.','2026-01-07 06:13:44',3),(7,'contact','email','support@disha.finance','2026-01-07 06:13:44',3),(8,'contact','phone','+91 90000 00000','2026-01-07 06:13:44',3),(9,'contact','address','123 Demo Street, Bangalore, India','2026-01-07 06:13:44',3);
